import * as vscode from 'vscode';
import { getWebViewContent, SocketPlugin } from '../utils';

let g_websocket: SocketPlugin | null;
export let g_SyslabAttributeView: vscode.WebviewView;
export let g_SyslabAttributeViewProvider: SyslabAttributeProvider;
export function activate(context: vscode.ExtensionContext) {
  // registerCommand('SyslabOnline.python_attribute',(websocketId:string)=>{
  //     createWebSocketConnect(websocketId);
  // });
  g_SyslabAttributeViewProvider = new SyslabAttributeProvider(
    context.extensionUri,
    context
  );
  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider(
      SyslabAttributeProvider.viewType,
      g_SyslabAttributeViewProvider
    )
  );
}

class SyslabAttributeProvider implements vscode.WebviewViewProvider {
  public static readonly viewType = 'SyslabAttributes';

  private _view?: vscode.WebviewView;

  private context: vscode.ExtensionContext;
  constructor(
    private readonly _extensionUri: vscode.Uri,
    context: vscode.ExtensionContext
  ) {
    this.context = context;
  }
  public resolveWebviewView(
    view: vscode.WebviewView,
    context: vscode.WebviewViewResolveContext,
    _token: vscode.CancellationToken
  ) {
    this._view = view;
    view.webview.options = {
      enableScripts: true,
      localResourceRoots: [this._extensionUri],
    };
    view.webview.html = getWebViewContent(
      this.context,
      'view/attribute.html',
      view.webview
    );
    g_SyslabAttributeView = view;
    this._view.webview.onDidReceiveMessage((msg) => {
      // 接收消息
     if(msg.type === 'mounted'){
        // 初始化属性面板
        if (g_websocket) {
          const data = { type: 'property_init' };
          g_websocket.send(JSON.stringify(data));
        }
      } 
      else if (msg.type === 'update') {
        if (g_websocket) {
          const msgData = {
            type: 'set_prop',
            label: msg.key,
            value: msg.value,
          };
          g_websocket.send(JSON.stringify(msgData));
        }
      } else if (msg.type === 'click_attribute_tab') {
        if (g_websocket) {
          const msgData = {
            type: 'change_select_objs',
            name: msg.value,
          };
          g_websocket.send(JSON.stringify(msgData));
        }
      }
    });
  }
  // 刷新figure
  refreshFigure(data: any) {}

  // 更新数据
  updateFigure(data: any) {}
}

// 创建websocket连接
export function createWebSocketConnect(url: string) {
  if (g_websocket) {
    g_websocket.close();
    g_websocket = null;
  }
  g_websocket = new SocketPlugin({ url });

  g_websocket.onopen = function () {
    const data = { type: 'property_ready' };
    g_websocket!.send(JSON.stringify(data));
  };
  g_websocket.onmessage = function (evt) {
    if (
      typeof evt.data === 'string' &&
      evt.data.slice(0, 21) !== 'data:image/png;base64'
    ) {
      const data = JSON.parse(evt.data);
      //   //console.log('属性面板接收到的消息', data);
      switch (data.type) {
        // 获取属性面板的数据
        case 'property_ready': {
          setTimeout(() => {
            g_SyslabAttributeView.webview.postMessage({
              type: 'init_attribute',
              value: data.props,
              current_prop: data.current_prop,
              font_list: data.font_list,
              platform: process.platform,
              language: vscode.env.language,
            });
          }, 100);
          break;
        }
        case 'property_init': {
          setTimeout(() => {
            g_SyslabAttributeView.webview.postMessage({
              type: 'init_attribute',
              value: data.props,
              current_prop: data.current_prop,
              font_list: data.font_list,
              platform: process.platform,
              language: vscode.env.language,
            });
          }, 100);
          break;
        }
        case 'property_change':{
          g_SyslabAttributeView.webview.postMessage({
            type: 'change_property',
            current_prop: data.current_prop,
            platform: process.platform,
            language: vscode.env.language,
          });
          break;
        }
        case 'property_update':{
          //console.log(data);
          g_SyslabAttributeView.webview.postMessage({
            type: 'update_property',
            value:data.value,
            key: data.key,
            child_key:data.child_key ? data.child_key : null,
            platform: process.platform,
            language: vscode.env.language,
          });
          break;
        }
        case 'reconnect':{
          g_websocket!.reconnect();
          break;
        }
        case 'close':{
          // vscode.window.showWarningMessage(
          //   `Figure异常，该Figure属性面板不可用，请重新绘图并打开属性面板。`
          // );
          console.log('Figure异常，该Figure属性面板不可用，请重新绘图并打开属性面板');
          g_websocket!.close();
          break;
        }
        case 'property_remove':{
          g_SyslabAttributeView.webview.postMessage({
            type: 'remove_property',
            current_prop: data.current_prop,
            del_prop:data.del_prop,
            platform: process.platform,
            language: vscode.env.language,
          });
          break;
        }
      }
    }
  };
  g_websocket.onclose = function () {
    console.warn('属性面板连接关闭');
  };
  g_websocket.onerror = function (e) {
    console.error('属性面板连接错误',e);
  };
  g_websocket.onreconnect = () => {
    //console.log('属性面板开始重连');
  };
  g_websocket.ontimeout = () => {
    console.error('属性面板重连超时');
  };
}

export function closeSyslabAttributeView() {
  if (g_websocket) {
    g_websocket.close();
    g_websocket = null;
  }
  //console.log('属性面板关闭');
}
let attributeTimer:NodeJS.Timeout | null;
export function readyAttributeView(url:string){
    if(attributeTimer){
      clearTimeout(attributeTimer);
      attributeTimer = null;
    }
    attributeTimer = setTimeout(() => {
      createWebSocketConnect(url);
      
    }, 10);
    // g_SyslabAttributeView.webview.postMessage({
    //   type: 'attribute_ready',
    // });
}
