export async function showStaticImg(
  figId: string, 
  title?: string,
  fignum?: string,
  
  backend?: string,
  figPklPath?:string,

) {
  const plotTitle = title ? title : `Figure_${figId}(python)`;

  if (figId && g_mapWebviewPanels.has(figId)) {
    // 复用窗口
    const panel = g_mapWebviewPanels.get(figId);
    if (panel) {
      if(panel?.backend && backend){
        panel.backend = backend;
      }
      panel.WebviewPanel.reveal(panel.WebviewPanel.viewColumn, true);
      panel.WebviewPanel.webview.postMessage({
        type: 'loaded',
        value: figId,
        platform: process.platform,
        language: vscode.env.language,
        port: webagg_port,
        imageBaseUrl:
          panel.WebviewPanel.webview.asWebviewUri(
            vscode.Uri.file(path.join(g_context.extensionPath, 'lib', 'webagg'))
          ) + '/',
      });
      // getStaticImg(figId, panel.WebviewPanel.webview.postMessage);
      getHttp(`/getPngBase64?port=${webagg_port}&figId=${figId}`)
        .then((res) => {
          panel.WebviewPanel.webview.postMessage({
            type: 'static_img',
            value: res?.value,
          });
        })
        .catch((err) => {
          console.log('静态绘图异常:请检查绘图代码并重新绘图',err);
          // vscode.window.showWarningMessage(
          //   `静态绘图异常:请检查绘图代码并重新绘图。${err}`
          // );
        });
    }
    return panel;
  } else {
    // 新建窗口
    // TODO:获取绘图频率限制参数
    const panel = vscode.window.createWebviewPanel(
      'Syslab_plot', // viewType
      plotTitle, // 视图标题
      {
        viewColumn:vscode.ViewColumn.Two,
        preserveFocus:true
      }, // 显示在编辑器的哪个部位
      {
        enableScripts: true, // 启用JS，默认禁用
        retainContextWhenHidden: true, // webview被隐藏时保持状态，避免被重置
      }
    );
     panel.webview.html = getWebViewContent(
      g_context,
      'view/webagg.html',
      panel.webview
    ); 
    // 单独构建一个div的容器显示webview的html
    // 打印webview的html
    console.log('webview的html', panel.webview.html);
    // 执行命令
    const url = `ws://localhost:${webagg_port}/${figId}/ws`;
    const webviewPanel: SyslabPlotPanel = <SyslabPlotPanel>{};
    webviewPanel.WebviewPanel = panel;
    webviewPanel.figure_id = figId;
    webviewPanel.websocket_url = url;
    webviewPanel.mode = 'static';
    webviewPanel.attribute_url = `ws://localhost:${webagg_port}/${figId}/attribute/ws`;
    webviewPanel.backend = backend;
    if (fignum) {
      webviewPanel.fignum = fignum;
    }
    // webviewPanel.ws = init_websocket(url, panel.webview.postMessage);
    g_mapWebviewPanels.set(figId, webviewPanel);
    // g_figures.set(figId, url);
    // 设置Typlot绘图窗口激活状态
    const viewStateListener = panel.onDidChangeViewState((changePanel) => {
      console.log('对窗口切换的回调changePanel', changePanel);
      // active_figure = webviewPanel;
      if (changePanel.webviewPanel.active) {
        updateActiveFigure();
      }else {
        vscode.commands.executeCommand(
          'setContext',
          c_TyPlotPanelActiveContextKey,
          false
        );
      }
    });
    // active_figure = webviewPanel;
    updateActiveFigure();
    // const res = await getHttp(
    //   `/setActiveFigure?port=${webagg_port}&figId=${figId}`
    // );
  
    //消息监听
    panel.webview.onDidReceiveMessage(async (msg) => {
      console.log('监听窗口返回信息的回调webview.onDidReceiveMessage', msg);
      switch (msg.type) {
        case 'ws_send': {
          if (webviewPanel.ws && webviewPanel.ws.readyState == 1) {
            webviewPanel.ws.send(JSON.stringify(msg.value));
          }
          break;
        }
        case 'init_websocket': {
          webviewPanel.ws = init_websocket(url, panel);
          break;
        }
        case 'loaded': {
          setTimeout(() => {
            panel.webview.postMessage({
              type: 'loaded',
              value: figId,
              platform: process.platform,
              language: vscode.env.language,
              ISONLINE: process.env.ISONLINE,
              port: webagg_port,
              imageBaseUrl:
                panel.webview.asWebviewUri(
                  vscode.Uri.file(
                    path.join(g_context.extensionPath, 'lib', 'webagg')
                  )
                ) + '/',
            });
            // getStaticImg(figId, panel.webview.postMessage);
            getHttp(`/getPngBase64?port=${webagg_port}&figId=${figId}`)
              .then((res) => {
                panel.webview.postMessage({
                  type: 'static_img',
                  value: res?.value,
                });
              })
              .catch((err) => {
                console.log('静态绘图异常:请检查绘图代码并重新绘图',err);
                // vscode.window.showWarningMessage(
                //   `静态绘图异常:请检查绘图代码并重新绘图。${err}`
                // );
              });
          }, 1000);
          break;
        }
        case 'property_setting': {
          //console.log('property_setting');

          attributeVisible = !attributeVisible;
          vscode.commands.executeCommand(
            'setContext',
            c_TyPlotAttributeVisible,
            attributeVisible
          );
          if (attributeVisible === true && active_figure) {
            vscode.commands.executeCommand('open-local-workspace');
            active_figure.ws!.send(
              JSON.stringify({
                type: 'property_init',
                id: active_figure.figure_id,
              })
            );
          } else if (attributeVisible === false) {
            closeSyslabAttributeView();
          }
          break;
        }
        case 'property_ready': {
          if (attributeVisible === true && active_figure) {
            readyAttributeView(active_figure.attribute_url);
          }
          break;
        }
        case 'initWebaggFigure': {
          let count = 0;
          let figPklPathStr = figPklPath?`&figPklPath=${figPklPath}`:"";
          // 读取syslab-config.json
          if (webviewPanel.backend === 'julia') {
            const config = JSON.parse(fs.readFileSync(`${os.homedir().replace(/\\/g,'/')}/SyslabCloud/.syslab-oss/syslab-config.json`,'utf-8'));
            const userFigPath = config['user-fig-path'];
            const res = await vscode.commands.executeCommand(
              'language-julia.exportFigWithId',
              figId,
              `${userFigPath}/figure_dir/${figId}.pkl`
            );
            if(!res){
              panel.webview.postMessage({
                type: 'mode_change',
                value: 'static',
              });
              vscode.commands.executeCommand(
                'setContext',
                c_TyPlotPanelActiveStatus,
                'static'
              );
              vscode.window.showErrorMessage(
                '序列化文件失败'
              );
              break;
            }
          }
          const timer = setInterval(async () => {
            const res = await getHttp(
              `/fileExists?figId=${figId}&port=${webagg_port}${figPklPathStr}`
            );
            count++;
            if (res.status) {
              clearInterval(timer);

              const initRes = await getHttp(
                `/initFigure?port=${webagg_port}&figId=${figId}${figPklPathStr}`
              );
              if (initRes.status && initRes.message === 'success') {
                const mouseMoveInterval = vscode.workspace
                .getConfiguration()
                .get<string>('plot.mouseMoveInterval');
                const mouseDragInterval = vscode.workspace
                .getConfiguration()
                .get<string>('plot.mouseDragInterval');
                panel.webview.postMessage({ type: 'initFigure',value:{mouseMoveInterval,mouseDragInterval} });
                const newDate = new Date().getTime();


              } else {
                console.log('交互模式初始化异常:请检查绘图代码并重新绘图');
                // vscode.window.showWarningMessage(
                //   `交互模式初始化异常:请检查绘图代码并重新绘图。`
                // );
              }
            } else {
              if (count >= 50) {
                clearInterval(timer);
                panel.webview.postMessage({
                  type: 'mode_change',
                  value: 'static',
                });
                vscode.commands.executeCommand(
                  'setContext',
                  c_TyPlotPanelActiveStatus,
                  'static'
                );
                vscode.window.showErrorMessage(
                  '交互模式初始化失败，请关闭绘图窗口后重新运行'
                );
              }
            }
          }, 100);
          break;
        }
        case 'download': {
          let defaultPath = vscode.workspace.workspaceFolders
            ? vscode.workspace.workspaceFolders[0]?.uri.fsPath
            : undefined;
          //console.log(vscode.workspace.workspaceFolders, defaultPath);
          if (defaultPath) {
            // defaultUri = defaultUri.with({
            //   path: defaultUri.fsPath + `/${active_figure!.WebviewPanel.title}.png`,
            // });
            defaultPath = path.join(
              defaultPath,
              `${active_figure!.WebviewPanel.title}.${msg.value}`
            );
          } else {
            defaultPath = path.join(
              os.homedir(),
              `${active_figure!.WebviewPanel.title}.${msg.value}`
            );
          }
          const result = await vscode.window.showSaveDialog({
            saveLabel: '保存',
            title: '保存图片',
            defaultUri: vscode.Uri.file(defaultPath!),
            filters: {
              图片: ['jpg', 'pdf', 'png', 'svg', 'tif'],
            },
          });
          if (result) {
            const option = {
              hostname: 'localhost',
              port: webagg_port,
              path: '/download',
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
              },
            };
            const req = http.request(option, (res) => {
              // //console.log(res);
              res.on('data', (data) => {
                const res = JSON.parse(data.toString());
                if (res.status) {
                  vscode.window.showInformationMessage(
                    '保存图片成功' + result.fsPath
                  );
                } else {
                  vscode.window.showErrorMessage(
                    '保存图片失败' + result.fsPath
                  );
                }
              });
            });
            // req.on('response',(res) => {
            //   //console.log('http请求返回值',res);
            // });
            req.on('error', (err) => {
              //console.log('http请求错误', err);
            });
            const data = {
              figId,
              fmt: msg.value,
              filename: result.fsPath,
            };
            req.write(JSON.stringify(data));
            req.end();
          }

          break;
        }
        case 'save_img_res': {
          if (msg.status) {
            let defaultPath = vscode.workspace.workspaceFolders
              ? vscode.workspace.workspaceFolders[0]?.uri.fsPath
              : undefined;
            //console.log(vscode.workspace.workspaceFolders, defaultPath);
            if (defaultPath) {
              // defaultUri = defaultUri.with({
              //   path: defaultUri.fsPath + `/${active_figure!.WebviewPanel.title}.png`,
              // });
              defaultPath = path.join(
                defaultPath!,
                `${active_figure!.WebviewPanel.title}.png`
              );
            } else {
              defaultPath = path.join(
                os.homedir(),
                `${active_figure!.WebviewPanel.title}.png`
              );
            }
            vscode.window
              .showSaveDialog({
                saveLabel: '保存',
                title: '保存图片',
                defaultUri: vscode.Uri.file(defaultPath),
                filters: {
                  图片: ['png'],
                },
              })
              .then((result) => {
                //console.log('保存的路径', result);
                if (result) {
                  // let filePath = result.path;

                  // if (process.platform === 'win32') {
                  //   filePath = filePath.replace(/^\//, '');
                  // }
                  const matches = msg.value.match(
                    /^data:([A-Za-z-+/]+);base64,(.+)$/
                  );
                  // const imageType = matches[1]; // 图片类型，例如 'image/png'
                  const encodedData = matches[2]; // 图片的 Base64 内容
                  // const writeStream = fs.createWriteStream(filePath);
                  const buffer = Buffer.from(encodedData, 'base64');
                  Promise.resolve();
                  try {
                    vscode.workspace.fs.writeFile(result, buffer);
                    vscode.window.showInformationMessage(
                      `图片已保存成功在：${result.fsPath}`
                    );
                  } catch (error) {
                    vscode.window.showErrorMessage(
                      `图片保存失败：${result.fsPath}`
                    );
                  }
                } else {
                  //console.log('取消', result);
                }
              });
            break;
          }
          break;
        }
        case 'websocket_close': {
          // console.warn('连接关闭');
          break;
        }
        case 'websocket_error': {
          console.log('网络连接错误',msg);
          // vscode.window.showWarningMessage(`网络连接错误:${msg.value}`);
          break;
        }
        case 'websocket_reconnect': {
          //console.log('开始重连');
          break;
        }
        case 'figure_not_find': {
          //console.log('开始重连');
          console.log('figure_not_find', `Figure异常:${panel.title}交互模式不可用，请关闭该绘图窗口并重新绘图。`);
          // vscode.window.showWarningMessage(
          //   `Figure异常:${panel.title}交互模式不可用，请关闭该绘图窗口并重新绘图。`
          // );
          break;
        }
        case 'websocket_timeout': {
          console.log('网络连接超时，请关闭绘图窗口并重启绘图服务');
          // vscode.window
          //   .showWarningMessage(
          //     `网络连接超时，请关闭绘图窗口并重启绘图服务`,
          //     { modal: false },
          //     { title: '重启绘图服务', isCloseAffordance: true }
          //   )
          //   .then((res) => {
          //     if (res?.title === '重启绘图服务') {
          //       restartWebaggServer();
          //     }
          //   });
          break;
        }
        case 'initFigureImageError': {
          console.log('initFigureImageError','静态绘图异常:请检查绘图代码并重新绘图',msg);
          // vscode.window.showWarningMessage(
          //   `静态绘图异常:请检查绘图代码并重新绘图。${msg.value}`
          // );
          break;
        }
        case 'initFigureError': {
          console.log('initFigureError','交互模式初始化异常:请检查绘图代码并重新绘图',msg);
          // vscode.window.showWarningMessage(
          //   `交互模式初始化异常:请检查绘图代码并重新绘图。${msg.value}`
          // );
          break;
        }
        case 'fileNotExists': {
          vscode.commands.executeCommand(
            'setContext',
            c_TyPlotPanelActiveStatus,
            'static'
          );
          vscode.window.showErrorMessage(`${msg.value}`);
          break;
        }
        case 'updateFigure': {
          let figPklPathStr = figPklPath?`&figPklPath=${figPklPath}`:"";
          getHttp(`/updateFigure?port=${webagg_port}&figId=${figId}${figPklPathStr}`)
            .then((res) => {
              vscode.window.showInformationMessage(
                `交互模式同步:${res.message}`
              );
            })
            .catch((e) => {
              console.log(`交互模式同步异常:请检查绘图代码并重新绘图${e ? e : ''}`);
              // vscode.window.showWarningMessage(
              //   `交互模式同步异常:请检查绘图代码并重新绘图。${e ? e : ''}`
              // );
            });
          break;
        }
        case 'updateFigureSuccess': {
          vscode.window.showInformationMessage(`交互模式同步:${msg.value}`);
          break;
        }
        case 'updateFigureError': {
          console.log('updateFigureError','交互模式同步异常:请检查绘图代码并重新绘图',msg);
          // vscode.window.showWarningMessage(
          //   `交互模式同步异常:请检查绘图代码并重新绘图。${
          //     msg.value ? msg.value : ''
          //   }`
          // );
          break;
        }
        case 'export_csv': {
          export_figure(figId, 'csv', 'csv', '/exportcsv');
          break;
        }
        case 'export_fig': {
          export_figure(figId, 'Syslab Figure', 'syslabfig', '/export_figure');
          break;
        }
        case 'import_fig': {
          import_figure('syslabfig', figId, false);
          break;
        }
        case 'import_current_fig': {
          import_figure('syslabfig', figId, true);
          break;
        }
      }
    });

    panel.onDidDispose(
      (e) => {
        viewStateListener.dispose();
        // g_figures.delete(figId);
        g_mapWebviewPanels.delete(figId);
        if (webviewPanel.ws) {
          webviewPanel.ws.close();
          webviewPanel.ws = null;
        }
        if (fignum) {
          vscode.commands.executeCommand(
            'language-julia.disposePlot',
            webviewPanel.fignum
          );
        }
        getHttp(`/removeWebaggFigure?figId=${figId}`)
          .then((res) => {
            console.log('删除成功');
          })
          .catch((e) => {
            console.error('删除失败');
          });
        if (g_mapWebviewPanels.size === 0) {
          vscode.commands.executeCommand(
            'setContext',
            c_TyPlotAttributeVisible,
            false
          );
          closeSyslabAttributeView();
        }
        updateActiveFigure();
      },
      null,
      g_context.subscriptions
    );
  }
  
}
// 导入fig
async function export_figure(
  figId: string,
  file_type_name: string,
  file_type: string,
  export_api: string
) {
  let defaultPath = vscode.workspace.workspaceFolders
    ? vscode.workspace.workspaceFolders[0]?.uri.fsPath
    : undefined;
  //console.log(vscode.workspace.workspaceFolders, defaultPath);
  if (defaultPath) {
    defaultPath = path.join(
      defaultPath,
      `${active_figure!.WebviewPanel.title}.${file_type}`
    );
  } else {
    defaultPath = path.join(
      process.env.USER_DATA_DIR || os.homedir(),
      `${active_figure!.WebviewPanel.title}.${file_type}`
    );
  }
  const result = await vscode.window.showSaveDialog({
    saveLabel: '保存',
    title: `保存为${file_type_name}`,
    defaultUri: vscode.Uri.file(defaultPath),
    filters: {
      [file_type]: [file_type],
    },
  });

  if (result) {
    vscode.window.withProgress(
      {
        location: vscode.ProgressLocation.Notification,
        title: '',
        cancellable: false,
      },
      (progress, token) => {
        const p = new Promise<void>((resolve) => {
          g_progress = {
            progress: progress,
            resolve: resolve,
          };
          progress.report({
            message: `正在导出${file_type_name}文件到` + result.fsPath,
          });
          const option = {
            hostname: 'localhost',
            port: webagg_port,
            path: export_api,
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
          };
          const req = http.request(option, (res) => {
            res.on('data', (data) => {
              const res = JSON.parse(data.toString());
              if (res.status) {
                vscode.window.showInformationMessage(
                  `导出${file_type_name}文件成功` + result.fsPath
                );
              } else {
                vscode.window.showErrorMessage(
                  `导出${file_type_name}文件失败` + result.fsPath
                );
              }
              clearProgress();
            });
          });
          req.on('error', (err) => {
            vscode.window.showErrorMessage(
              `导出${file_type_name}文件失败` + result.fsPath
            );
            clearProgress();
          });
          req.on('timeout', () => {
            vscode.window.showErrorMessage(
              `导出${file_type_name}文件失败` + result.fsPath
            );
            clearProgress();
          });
          const data = {
            figId,
            filename: result.fsPath,
          };
          req.write(JSON.stringify(data));
          req.end();
        });
        return p;
      }
    );
  }
}
function changeFigureMode(status: 'dynamic' | 'static') {
  if (active_figure) {
    active_figure.WebviewPanel.webview.postMessage({
      type: 'mode_change',
      value: status,
      platform: process.platform,
      language: vscode.env.language,
    });
  }
}
//清除进度条
export function clearProgress() {
  if (g_progress.progress) {
    g_progress.resolve();
    g_progress = <ProgressStruct>{};
  }
}

function init_websocket(ws_url: string, panel: vscode.WebviewPanel) {
  let ws = new SocketPlugin({ url: ws_url });
  ws.onopen = () => {
    panel.webview.postMessage({
      type: 'ws_message',
      value: JSON.stringify({ type: 'init_websocket' }),
    });
  };
  ws.onmessage = (e) => {
    panel.webview.postMessage({ type: 'ws_message', value: e.data });
  };
  ws.onclose = () => {
    console.log('图窗连接关闭');
  };
  ws.onerror = (e: any) => {
    console.log(`网络连接错误:${JSON.stringify(e)}`);
    // vscode.window.showWarningMessage(`网络连接错误:${JSON.stringify(e)}`);
  };
  ws.onreconnect = () => {};
  ws.ontimeout = () => {
    console.log('网络连接超时，请关闭绘图窗口并重启绘图服务');
    // vscode.window
    //   .showWarningMessage(
    //     `网络连接超时，请关闭绘图窗口并重启绘图服务`,
    //     { modal: false },
    //     { title: '重启绘图服务', isCloseAffordance: true }
    //   )
    //   .then((res) => {
    //     if (res?.title === '重启绘图服务') {
    //       restartWebaggServer();
    //     }
    //   });
  };
  return ws;
}
function getHttp(path: string): Promise<RES | any> {
  return new Promise((resolve, reject) => {
    const option = {
      hostname: 'localhost',
      port: webagg_port,
      path,
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
    };
    const chunk: Array<Buffer> = [];
    // let chunkStr: string = '';
    const req = http.request(option, (res) => {
      res.on('data', (data) => {
        chunk.push(data);
        // chunkStr += data
      });
      res.on('end', () => {
        const httpData: RES = JSON.parse(Buffer.concat(chunk).toString());
        console.log("get发送的请求是option：", option, "请求返回的结果res:", httpData);
        // const httpData: RES = JSON.parse(chunkStr);
        if (httpData.status && httpData.message) {
          resolve(httpData);
        } else {
          resolve(httpData);
        }
      });
    });
    req.on('error', (err) => {
      reject(err);
    });
    req.end();
  });
}
function postHttp(path: string,data?: any): Promise<RES | any> {
  return new Promise((resolve, reject) => {
    const option = {
      hostname: 'localhost',
      port: webagg_port,
      path,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...data.getHeaders()
      },
    };
    const chunk: Array<Buffer> = [];
    const req = http.request(option, (res) => {
      // //console.log(res);
      res.on('data', (data) => {
        chunk.push(data);
      });
      res.on('end', () => {
        const httpData: RES = JSON.parse(Buffer.concat(chunk).toString());
        console.log("post发送的请求是option：", option, "请求返回的结果res:", httpData);
        if (httpData.status && httpData.message) {
          resolve(httpData);
        } else {
          reject(httpData.message);
        }
      });
    });
    req.on('error', (err) => {
      reject(err);
    });
    if (data) {
      data?.pipe(req);
      return;
    }
    req.end();
  });
}

async function import_figure(
  file_type: string = 'syslabfig',
  figId?: string,
  isCurrent?: boolean
) {
  let defaultPath = vscode.workspace.workspaceFolders
    ? vscode.workspace.workspaceFolders[0]?.uri.fsPath
    : os.homedir();
  //console.log(vscode.workspace.workspaceFolders, defaultPath);
  // if (defaultPath) {
  //   defaultPath = path.join(
  //     defaultPath,
  //     `${active_figure!.WebviewPanel.title}.${file_type}`
  //   );
  // } else {
  //   defaultPath = path.join(
  //     os.homedir(),
  //     `${active_figure!.WebviewPanel.title}.${file_type}`
  //   );
  // }
  const result = await vscode.window.showOpenDialog({
    openLabel: '导入',
    title: `导入文件`,
    defaultUri: vscode.Uri.file(defaultPath),
    filters: {
      SyslabFig: ['syslabfig'],
    },
    canSelectFolders: false,
  });
  if (result) {
    const option = {
      hostname: 'localhost',
      port: webagg_port,
      path: '/import_figure',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
    };
    const req = http.request(option, (res) => {
      res.on('data', (data) => {
        const res = JSON.parse(data.toString());
        if (res.status) {
          vscode.window.showInformationMessage(
            `导入文件成功` + result[0].fsPath
          );
        } else {
          vscode.window.showErrorMessage(res.message);
        }
        clearProgress();
      });
    });
    req.on('error', (err) => {
      vscode.window.showErrorMessage(`导入文件失败` + result[0].fsPath);
      clearProgress();
    });
    req.on('timeout', () => {
      vscode.window.showErrorMessage(`导入文件失败` + result[0].fsPath);
      clearProgress();
    });
    const data = {
      filename: result[0].fsPath,
      userId: g_userid,
      figId: figId || null,
      isCurrent: isCurrent || false,
    };
    req.write(JSON.stringify(data));
    req.end();
  }
}

