import * as vscode from 'vscode';
import * as fs from 'fs';
import * as path from 'path';
import { WebSocket } from 'ws';

/**
 * @description: 注册命令
 * @param cmd 
 * @param f 
 * @returns 
 */
export function registerCommand(cmd: string, f: any) {
  const fWrapped = (...args: any[]) => {
    try {
      return f(...args);
    } catch (err) {
      // handleNewCrashReportFromException(err, 'Extension');
      throw err;
    }
  };
  return vscode.commands.registerCommand(cmd, fWrapped);
}
/**
 * @description: 获取webview内容 返回html
 * @param context  上下文
 * @param templatePath  模板路径
 * @param view  webview
 * @returns  html
 */
export function getWebViewContent(
  context: any,
  templatePath: string,
  view: vscode.Webview
) {
  const resourcePath = path.join(context.extensionPath, templatePath);
  // const dirPath = path.dirname(resourcePath)
  let html = fs.readFileSync(resourcePath, 'utf-8');
  // vscode不支持直接加载本地资源，需要替换成其专有路径格式，这里只是简单的将样式和JS的路径替换
  html = html.replace(
    /(<link.+?href="|<script.+?src="|<img.+?src=")(.+?)"/g,
    (m, $1, $2) => {
      // return $1 + vscode.Uri.file(path.resolve(dirPath, $2)).with({ scheme: 'vscode-resource' }).toString() + '"'
      if (m.indexOf('type="dynamic"') !== -1) {
        return m;
      }
      return (
        $1 +
        view.asWebviewUri(
          vscode.Uri.file(path.join(context.extensionPath, 'view', $2))
        ) +
        '"'
      );
    }
  );
  return html;
}

