export class SocketPlugin {
  // websocket实例
  opts = {
    url: '', // websocket地址
    pongTimeout: 10000, // 心跳检测超时时间
    repeatLimit: 5, // 重连次数限制
  };

  ws:any; // websocket实例

  readyState:any; // websocket实例状态

  repeatNum = 0; // 重连次数

  reconnectTimes = [0,5,5,10,10,10,10,10,30]; // 重连间隔时间

  onclose; // websocket关闭回调

  onerror; // websocket错误回调

  onopen; // websocket打开回调

  onmessage; // websocket消息回调

  onreconnect; // websocket重连回调

  ontimeout; // websocket超时回调

  lockReconnect = false; // 锁定重连

  forbidReconnect = false; // 禁止重连

  pongTimeoutId:any; // 心跳检测超时id
  heartbeatTimeoutId:any; // 心跳检测id

  constructor(params:any) {
    this.opts = {
      url: params.url,
      pongTimeout: params?.pongTimeout || 10000,
      repeatLimit: params?.repeatLimit || 5,
    };
    this.ws = null; // websocket实例
    this.repeatNum = 0;

    this.onclose = () => {};
    this.onerror = (error:any) => {};
    this.onopen = () => {};
    this.onmessage = (event:any) => {};
    this.onreconnect = () => {};
    this.ontimeout = () => {};

    this.createWebSocket();
  }

  createWebSocket() {
    try {
      if(this.ws){
        this.ws.close();
      }
      this.ws = new WebSocket(this.opts.url);
      this.initEventHandle();
    } catch (e) {
      this.reconnect();
      throw e;
    }
  }
  // 初始化事件处理
  initEventHandle() {
    this.ws.onclose = () => {
      this.readyState = this.ws.readyState;
      this.heartbeatReset();
      this.onclose();
    };
    this.ws.onerror = (error:any) => {
      this.readyState = this.ws.readyState;
      this.onerror(error);
      this.reconnect();
    };
    this.ws.onopen = () => {
      this.readyState = this.ws.readyState;
      this.repeatNum = 0;
      this.heartbeatInit();
      this.onopen();
    };
    this.ws.onmessage = (event:any) => {
      this.readyState = this.ws.readyState;

      // 如果获取到消息，心跳检测重置
      // 拿到任何消息都说明当前连接是正常的
      this.pongReset();
      this.onmessage(event);
    };
  }
  // 重连
  reconnect() {
    this.pongReset();
    this.heartbeatReset();
    this.ws.close();
    if (this.opts.repeatLimit > 0 && this.opts.repeatLimit <= this.repeatNum) {
      this.close();
      this.ontimeout();
      return;
    } // limit repeatNum the number
    if (this.lockReconnect || this.forbidReconnect) {
      return;
    }
    this.lockReconnect = true;
    this.onreconnect();
    // 没连接上会一直重连，设置延迟避免请求过多
    setTimeout(() => {
      this.createWebSocket();
      this.lockReconnect = false;
    }, this.reconnectTimes[this.repeatNum]);
    this.repeatNum++; // 必须在lockReconnect之后，避免进行无效计数
  }

  send(msg:any) {
    // 如果正在重连或主动关闭websocket则不发送消息
    if(this.lockReconnect || this.forbidReconnect){
      return;
    }
    // if(JSON.parse(msg).type==='draw'){
      // console.log(msg);
    // }
    // 发送消息时判断websocket状态，断开则进行重连
    if (this.ws&&this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(msg);
      if(!this.pongTimeoutId){
        this.pongTimeoutReconnect();
      }
    }else{
      // 断开则进行重连
      this.reconnect();
    }
  }
  // 心跳检测
  heartbeatInit(){
    if(this.heartbeatTimeoutId){
      clearInterval(this.heartbeatTimeoutId);
      this.heartbeatTimeoutId=null;
    }
    this.heartbeatTimeoutId = setInterval(()=>{
      this.send(JSON.stringify({type:'heartbeat'}));
    },3000);
  }
  heartbeatReset(){
    if(this.heartbeatTimeoutId){
      clearInterval(this.heartbeatTimeoutId);
      this.heartbeatTimeoutId=null;
    }
  }
  // 心跳检测超时重连
  pongTimeoutReconnect(){
    this.pongTimeoutId = setTimeout(() => {
      // 进行响应计时，超时则重连
      if(this.ws.readyState !== WebSocket.OPEN){
        console.log('heart break---');
        this.reconnect();
      }else{
        this.pongReset();
        this.pongTimeoutReconnect();
      }
    }, this.opts.pongTimeout);
  }
// 心跳检测重置 
  pongReset() {
    if(this.pongTimeoutId){
      clearTimeout(this.pongTimeoutId);
      this.pongTimeoutId=null;
    }
  }

  close() {
    console.log('手动关闭socket');
    // 如果手动关闭连接，不再重连
    this.forbidReconnect = true;
    this.pongReset();
    this.ws.close();
  }
}
/**
 * Description: 生成随机字符串
 * @returns 生成随机字符串
 */
export function generateRandomString() {
  let str = '';
  const characters =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  const charactersLength = characters.length;

  for (let i = 0; i < 6; i++) {
    str += characters.charAt(Math.floor(Math.random() * charactersLength));
  }

  return str;
}
